// seed script and background jobs call this service directly, and a digest
// hour outside 0-23 must never reach the scheduler.
//
// `organizationSettingsSchema` fills defaults for omitted keys. Parsing the
// patch with that object schema would turn a one-field save into a full
// settings rewrite (digest hour 7, flags cleared, 2FA off). Validate only
// keys the caller actually sent, including explicit 0, false, and [].
const patch: UpdateOrganizationInput =
  input.settings === undefined
    ? input
    : { ...input, settings: parseSettingsPatch(input.settings) };

